mapper.select:
SELECT /* kr.or.kids.domain.cm.community.dashboard.mapper.selectDashboardUploadNotice */ p.pblnt_sn AS pblntSn , p.pblnt_se_cd AS pblntSeCd -- pblnt_dvcd → pblnt_se_cd , p.ttl_nm AS ttlNm , p.pblnt_cn AS pblntCn , p.pblnt_bgng_ymd AS pblntBgngYmd , p.pblnt_end_ymd AS pblntEndYmd , p.pblnt_prgrs_stts_cd AS pblntPrgrsSttscd -- pblnt_stcd → pblnt_prgrs_stts_cd , COALESCE(A.part_cnt, 0) AS partCnt -- 참여기관수 , COALESCE(B.total_cnt, 0) AS totalCnt -- 전체 대상기관수 FROM kids_own.tb_cm_m_uld_pblnt P -- 참여기관 수 LEFT JOIN ( SELECT pblnt_sn , COUNT(DISTINCT inst_id) AS part_cnt FROM kids_own.tb_cm_m_uld_prst -- tm_cm_m_uld_prst → tb_cm_m_uld_prst WHERE del_yn = 'N' AND uld_inst_prgrs_stts_cd IN ('01','02','03','05','06','07') GROUP BY pblnt_sn ) A ON P.pblnt_sn = A.pblnt_sn -- 전체 대상기관 수 LEFT JOIN ( SELECT pblnt_sn , COUNT(DISTINCT inst_id) AS total_cnt FROM kids_own.tb_cm_m_uld_prst WHERE del_yn = 'N' GROUP BY pblnt_sn ) B ON P.pblnt_sn = B.pblnt_sn WHERE (P.del_yn IS NULL OR P.del_yn = 'N')
AND P.pblnt_se_cd = #{pblntSeCd}
AND P.ttl_nm LIKE CONCAT('%', #{keyword}, '%')
AND P.pblnt_cn LIKE CONCAT('%', #{keyword}, '%')
AND (P.ttl_nm LIKE CONCAT('%', #{keyword}, '%') OR P.pblnt_cn LIKE CONCAT('%', #{keyword}, '%'))
AND P.pblnt_bgng_ymd >= #{pblntBgngYmd}
AND P.pblnt_end_ymd <= #{pblntEndYmd}
ORDER BY P.reg_dt DESC LIMIT 10
